import{_ as t}from"./chunks/ellipse-inertial-navigation-system.D_NyCmbM.js";import{_ as a,c as s,o as r,al as o}from"./chunks/framework.CT7RwC5a.js";const g=JSON.parse('{"title":"SBG Systems INS/AHRS (Pulse, Ellipse, etc.)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/sensor/sbgecom.md","filePath":"uk/sensor/sbgecom.md"}'),i={name:"uk/sensor/sbgecom.md"};function n(l,e,c,d,h,m){return r(),s("div",null,e[0]||(e[0]=[o('<h1 id="sbg-systems-ins-ahrs-pulse-ellipse-etc" tabindex="-1">SBG Systems INS/AHRS (Pulse, Ellipse, etc.) <a class="header-anchor" href="#sbg-systems-ins-ahrs-pulse-ellipse-etc" aria-label="Permalink to &quot;SBG Systems INS/AHRS (Pulse, Ellipse, etc.)&quot;">​</a></h1><p><a href="https://www.sbg-systems.com/" target="_blank" rel="noreferrer">SBG-Systems</a> designs, manufactures, and support an extensive range of state-of-the-art inertial sensors such as Inertial Measurement Units (IMU), Attitude and Heading Reference Systems (AHRS), Inertial Navigation Systems with embedded GNSS (INS/GNSS), and so on.</p><p>PX4 supports <a href="https://www.sbg-systems.com/products/" target="_blank" rel="noreferrer">all SBG Systems products</a> and can use these as an <a href="./../sensor/inertial_navigation_systems.html">external INS</a> (bypassing/replacing the EKF2 estimator), or as a source of raw sensor data provided to the navigation estimator.</p><p><img src="'+t+'" alt="Ellipse"></p><h2 id="загальнии-огляд" tabindex="-1">Загальний огляд <a class="header-anchor" href="#загальнии-огляд" aria-label="Permalink to &quot;Загальний огляд&quot;">​</a></h2><p>SBG Systems products provide a range of benefits to PX4 users and can be integrated for:</p><ul><li>Вища точність оцінки напрямку, крену та кочення</li><li>Більш надійна геоприв&#39;язка GNSS</li><li>Покращена точність позиціонування та установки під час конфлікту супутникового зв&#39;язку</li><li>Продуктивність при динамічних умовах (наприклад, запуски катапультою, операції VTOL, високі g або високі операції з великою кутовою швидкістю)</li></ul><p>The sbgECom PX4 driver is streamlined to provide a simple plug-and-play architecture, removing engineering obstacles and allowing the acceleration of the design, development, and launch of platforms to keep pace with the rapid rate of innovation.</p><p>The driver supports <a href="https://www.sbg-systems.com/products/" target="_blank" rel="noreferrer">all SBG Systems products</a>. Зокрема, рекомендуємо наступні системи:</p><ul><li><strong>Pulse:</strong> Recommended for fixed-wing systems without hovering, where static heading is not necessary.</li><li><strong>Ellipse:</strong> Recommended for multicopter systems where hovering and low dynamics requires the use of static heading.</li></ul><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>SBG Systems solutions are available directly from <a href="https://my.sbg-systems.com" target="_blank" rel="noreferrer">MySBG</a> (FR) or through their Global Sales Representatives. For more information on their solutions or for international orders, please contact <a href="mailto:contact@sbg-systems.com" target="_blank" rel="noreferrer">contact@sbg-systems.com</a>.</p><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>Connect any unused flight controller serial interface, such as a spare <code>GPS</code> or <code>TELEM</code> port, to the SBG Systems product MAIN port (required by PX4).</p><h3 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h3><p>The SBG Systems product sensor can be mounted in any orientation, in any position on the vehicle, without regard to center of gravity. All SBG Systems product sensors default to a coordinate system of x-forward, y-right, and z-down, making the default mounting as connector-back, base down. This can be changed to any rigid rotation using the sbgECom Reference Frame Rotation register.</p><p>Якщо використовується продукт з підтримкою GNSS, антена GNSS повинна бути жорстко монтуватися щодо інерційного датчика та мати необмежений вид на небо. If using a dual-GNSS-enabled product (Ellipse-D), the secondary antenna must be mounted rigidly with respect to the primary antenna and the inertial sensor with an unobstructed sky view.</p><p>For more mounting and configuration requirements and recommendations, see the relevant <a href="https://support.sbg-systems.com/sc" target="_blank" rel="noreferrer">SBG SUPPORT CENTER</a>.</p><h2 id="конфігурація-прошивки" tabindex="-1">Конфігурація прошивки <a class="header-anchor" href="#конфігурація-прошивки" aria-label="Permalink to &quot;Конфігурація прошивки&quot;">​</a></h2><h3 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h3><p>To use the sbgECom driver:</p><ol><li><p>Include the module in firmware in the <a href="./../hardware/porting_guide_config.html#px4-board-configuration-kconfig">kconfig board configuration</a> by setting the kconfig variables: <code>CONFIG_DRIVERS_INS_SBGECOM</code> or <code>CONFIG_COMMON_INS</code>.</p></li><li><p><a href="./../advanced_config/parameters.html">Set the parameter</a> <a href="./../advanced_config/parameter_reference.html#SENS_SBG_CFG">SENS_SBG_CFG</a> to the hardware port connected to the SBG Systems product (for more information see <a href="./../peripherals/serial_configuration.html">Serial Port Configuration</a>).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Disable or change port of other sensors that are using the same one, for example <a href="./../advanced_config/parameter_reference.html#GPS_1_CONFIG">GPS_1_CONFIG</a> if using GPS1 port.</p></div></li></ol><p>:::</p><ol start="3"><li><p>Set <a href="./../advanced_config/parameter_reference.html#SBG_BAUDRATE">SBG_BAUDRATE</a> to the desired default baudrate value.</p></li><li><p>Allow the sbgECom driver to initialize by restarting PX4.</p></li><li><p>Configure driver to provide IMU data, GNSS data and INS :</p><ol><li>Set <a href="./../advanced_config/parameter_reference.html#SBG_MODE">SBG_MODE</a> to the desired mode.</li><li>Make sensor module select sensors by enabling <a href="./../advanced_config/parameter_reference.html#SENS_IMU_MODE">SENS_IMU_MODE</a>.</li><li>Prioritize SBG Systems sensors using <a href="./../advanced_config/parameter_reference.html#CAL_GYRO0_PRIO">CAL_GYROn_PRIO</a>, <a href="./../advanced_config/parameter_reference.html#CAL_ACC0_PRIO">CAL_ACCn_PRIO</a>, <a href="./../advanced_config/parameter_reference.html#CAL_BARO0_PRIO">CAL_BAROn_PRIO</a>, <a href="./../advanced_config/parameter_reference.html#CAL_MAG0_PRIO">CAL_MAGn_PRIO</a>, where <em>n</em> is the instance number of the IMU component (0, 1, etc.).</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In most cases the external IMU (SBG) is the highest-numbered. Ви можете отримати список доступних компонентів IMU, використовуючи <a href="./../middleware/uorb.html#uorb-top-command"><code>uorb top -1</code></a>, ви можете відрізняти їх за допомогою команди <a href="./../modules/modules_command.html#listener"><code>listener</code></a> та розглядаючи дані чи просто швидкості.</p><p>За потреби ви можете перевірити <a href="./../advanced_config/parameter_reference.html#CAL_GYRO0_ID">CAL_GYROn_ID</a>, щоб побачити ідентифікатор пристрою. Пріоритет становить 0-255, де 0 абсолютно вимкнено, а 255 - найвищий пріоритет.</p></div></li></ol><p>:::</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>When configuring both SBG Systems and Pixhawk sensors to have non-zero priority, if the selected sensor is errored (timeout), it can change during operation without being notified. In this case, MAVLink messages will be updated with the newly selected sensor.</p><p>If you don&#39;t want to have this fallback mechanism, you must disable unwanted sensors.</p></div><ol start="4"><li><p>If using the sbgECom as an INS, disable EKF2 using <a href="./../advanced_config/parameter_reference.html#EKF2_EN">EKF2_EN</a>.</p></li><li><p>Перезавантажте PX4.</p></li></ol><p>Після активації модуль буде виявлено при завантаженні. IMU data should be published at 200Hz.</p><h2 id="sbg-systems-configuration" tabindex="-1">SBG Systems Configuration <a class="header-anchor" href="#sbg-systems-configuration" aria-label="Permalink to &quot;SBG Systems Configuration&quot;">​</a></h2><p>All High Performance and Ellipse 3.0 and higher SBG Systems INS can be configured directly from PX4 firmware:</p><ol><li><p>Enable <a href="./../advanced_config/parameter_reference.html#SBG_CONFIGURATION_EN">SBG_CONFIGURATION_EN</a></p></li><li><p>Provide a JSON file <code>sbg_settings.json</code> containing SBG Systems INS settings to be applied in your PX4 board <code>extras</code> directory (ex: <code>boards/px4/fmu-v5/extras</code>). The settings JSON file will be installed in <code>/etc/extras/sbg_settings.json</code> on the board.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The settings can be retrieved using <a href="https://github.com/SBG-Systems/sbgECom/tree/main/tools/sbgEComApi" target="_blank" rel="noreferrer">sbgEComAPI</a> or <a href="https://developer.sbg-systems.com/sbgInsRestApi/1.3/#tag/Settings" target="_blank" rel="noreferrer">sbgInsRestApi</a> and then modified as a JSON file.</p></div></li></ol><p>:::</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The settings file can be provided in the SD card in q<code>/fs/microsd/etc/extras/sbg_settings.json</code> to avoid rebuilding a new firmware to change JSON settings file.</p></div><ol start="3"><li><p>For testing purpose, it&#39;s also possible to modify SBG Systems INS settings on the fly:</p><ul><li>By passing a JSON file path as argument when starting sbgecom driver (ex: <code>sbgecom start -f /fs/microsd/new_sbg_settings.json</code>)</li><li>By passing a JSON string as argument when starting sbgecom driver: (ex: <code>sbgecom start -s {&quot;output&quot;:{&quot;comA&quot;:{&quot;messages&quot;:{&quot;airData&quot;:&quot;onChange&quot;}}}}</code>)</li></ul></li></ol><p>For older Ellipse SBG Systems INS or to configure any SBG Systems INS directly, all commands and registers can be found in the <a href="https://support.sbg-systems.com/sc" target="_blank" rel="noreferrer">SBG SUPPORT CENTER</a>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If the baudrate of the serial port on the INS product (used to communicate with PX4) is changed, the parameter <a href="./../advanced_config/parameter_reference.html#SBG_BAUDRATE">SBG_BAUDRATE</a> must be changed to match.</p></div><h2 id="опубліковані-дані" tabindex="-1">Опубліковані дані <a class="header-anchor" href="#опубліковані-дані" aria-label="Permalink to &quot;Опубліковані дані&quot;">​</a></h2><p>При ініціалізації водій повинен надрукувати наступну інформацію до консолі (надруковано за допомогою <code>PX4_INFO</code>)</p><ul><li>Номер моделі блока</li><li>Версія апаратної одиниці</li><li>Номер серійного номеру блока</li><li>Номер прошивки одиниці</li></ul><p>Цей текст має бути доступний за допомогою команди <a href="./../modules/modules_system.html#dmesg"><code>dmesg</code></a>.</p><p>The sbgECom driver always publishes the unit&#39;s data to the following uORB topics:</p><ul><li><a href="./../msg_docs/SensorAccel.html">sensor_accel</a></li><li><a href="./../msg_docs/SensorGyro.html">датчик_гіроскопа</a></li><li><a href="./../msg_docs/SensorMag.html">sensor_mag</a></li></ul><p>if configured as a GNSS, publishes:</p><ul><li><a href="./../msg_docs/SensorGps.html">sensor_gps</a></li></ul><p>and, if configured as an INS, publishes:</p><ul><li><a href="./../msg_docs/EstimatorStatus.html">estimator_status</a></li><li><a href="./../msg_docs/VehicleLocalPosition.html">vehicle_local_position</a></li><li><a href="./../msg_docs/VehicleGlobalPosition.html">vehicle_global_positon</a></li><li><a href="./../msg_docs/VehicleAttitude.html">vehicle_attitude</a></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Опубліковані теми можна переглянути за допомогою команди <code>listener</code>.</p></div><h2 id="характеристики-обладнання" tabindex="-1">Характеристики обладнання <a class="header-anchor" href="#характеристики-обладнання" aria-label="Permalink to &quot;Характеристики обладнання&quot;">​</a></h2><ul><li><a href="https://www.sbg-systems.com/products/" target="_blank" rel="noreferrer">Product Briefs</a></li><li><a href="https://www.sbg-systems.com/contact/#products" target="_blank" rel="noreferrer">Datasheets</a></li></ul>',50)]))}const f=a(i,[["render",n]]);export{g as __pageData,f as default};
